class CartItemsModel {  CartItemsModel({    required this.cartItems,    required this.summary,  });  final List<CartItem> cartItems;  final Summary? summary;  factory CartItemsModel.fromJson(Map<String, dynamic> json){    return CartItemsModel(      cartItems: json["cart_items"] == null ? [] : List<CartItem>.from(json["cart_items"]!.map((x) => CartItem.fromJson(x))),      summary: json["summary"] == null ? null : Summary.fromJson(json["summary"]),    );  }  Map<String, dynamic> toJson() => {    "cart_items": cartItems.map((x) => x.toJson()).toList(),    "summary": summary?.toJson(),  };}class CartItem {  CartItem({    required this.id,    required this.userId,    required this.productId,    required this.colorId,    required this.sizeId,    required this.quantity,    required this.createdAt,    required this.updatedAt,    required this.product,    required this.color,    required this.size,  });  final int id;  final int userId;  final int productId;  final int colorId;  final int sizeId;  final int quantity;  final DateTime? createdAt;  final DateTime? updatedAt;  final Product? product;  final Color? color;  final Color? size;  factory CartItem.fromJson(Map<String, dynamic> json){    return CartItem(      id: json["id"] ?? 0,      userId: json["user_id"] ?? 0,      productId: json["product_id"] ?? 0,      colorId: json["color_id"] ?? 0,      sizeId: json["size_id"] ?? 0,      quantity: json["quantity"] ?? 0,      createdAt: DateTime.tryParse(json["created_at"] ?? ""),      updatedAt: DateTime.tryParse(json["updated_at"] ?? ""),      product: json["product"] == null ? null : Product.fromJson(json["product"]),      color: json["color"] == null ? null : Color.fromJson(json["color"]),      size: json["size"] == null ? null : Color.fromJson(json["size"]),    );  }  Map<String, dynamic> toJson() => {    "id": id,    "user_id": userId,    "product_id": productId,    "color_id": colorId,    "size_id": sizeId,    "quantity": quantity,    "created_at": createdAt?.toIso8601String(),    "updated_at": updatedAt?.toIso8601String(),    "product": product?.toJson(),    "color": color?.toJson(),    "size": size?.toJson(),  };}class Color {  Color({    required this.id,    required this.name,    required this.code,    required this.createdAt,    required this.updatedAt,  });  final int id;  final String name;  final String code;  final DateTime? createdAt;  final DateTime? updatedAt;  factory Color.fromJson(Map<String, dynamic> json){    return Color(      id: json["id"] ?? 0,      name: json["name"] ?? "",      code: json["code"] ?? "",      createdAt: DateTime.tryParse(json["created_at"] ?? ""),      updatedAt: DateTime.tryParse(json["updated_at"] ?? ""),    );  }  Map<String, dynamic> toJson() => {    "id": id,    "name": name,    "code": code,    "created_at": createdAt?.toIso8601String(),    "updated_at": updatedAt?.toIso8601String(),  };}class Product {  Product({    required this.id,    required this.name,    required this.slug,    required this.categoryId,    required this.description,    required this.additionalInfo,    required this.price,    required this.discountPrice,    required this.dimensions,    required this.featured,    required this.popular,    required this.status,    required this.quantity,    required this.createdAt,    required this.updatedAt,    required this.primaryImage,  });  final int id;  final String name;  final String slug;  final int categoryId;  final String description;  final String additionalInfo;  final String price;  final String discountPrice;  final String dimensions;  final int featured;  final int popular;  final int status;  final int quantity;  final DateTime? createdAt;  final DateTime? updatedAt;  final PrimaryImage? primaryImage;  factory Product.fromJson(Map<String, dynamic> json){    return Product(      id: json["id"] ?? 0,      name: json["name"] ?? "",      slug: json["slug"] ?? "",      categoryId: json["category_id"] ?? 0,      description: json["description"] ?? "",      additionalInfo: json["additional_info"] ?? "",      price: json["price"] ?? "",      discountPrice: json["discount_price"] ?? "",      dimensions: json["dimensions"] ?? "",      featured: json["featured"] ?? 0,      popular: json["popular"] ?? 0,      status: json["status"] ?? 0,      quantity: json["quantity"] ?? 0,      createdAt: DateTime.tryParse(json["created_at"] ?? ""),      updatedAt: DateTime.tryParse(json["updated_at"] ?? ""),      primaryImage: json["primary_image"] == null ? null : PrimaryImage.fromJson(json["primary_image"]),    );  }  Map<String, dynamic> toJson() => {    "id": id,    "name": name,    "slug": slug,    "category_id": categoryId,    "description": description,    "additional_info": additionalInfo,    "price": price,    "discount_price": discountPrice,    "dimensions": dimensions,    "featured": featured,    "popular": popular,    "status": status,    "quantity": quantity,    "created_at": createdAt?.toIso8601String(),    "updated_at": updatedAt?.toIso8601String(),    "primary_image": primaryImage?.toJson(),  };}class PrimaryImage {  PrimaryImage({    required this.id,    required this.productId,    required this.image,    required this.isPrimary,    required this.createdAt,    required this.updatedAt,  });  final int id;  final int productId;  final String image;  final int isPrimary;  final DateTime? createdAt;  final DateTime? updatedAt;  factory PrimaryImage.fromJson(Map<String, dynamic> json){    return PrimaryImage(      id: json["id"] ?? 0,      productId: json["product_id"] ?? 0,      image: json["image"] ?? "",      isPrimary: json["is_primary"] ?? 0,      createdAt: DateTime.tryParse(json["created_at"] ?? ""),      updatedAt: DateTime.tryParse(json["updated_at"] ?? ""),    );  }  Map<String, dynamic> toJson() => {    "id": id,    "product_id": productId,    "image": image,    "is_primary": isPrimary,    "created_at": createdAt?.toIso8601String(),    "updated_at": updatedAt?.toIso8601String(),  };}class Summary {  Summary({    required this.subtotal,    required this.couponDiscount,    required this.deliveryCharge,    required this.grandTotal,    required this.couponCode,  });  final int subtotal;  final int couponDiscount;  final int deliveryCharge;  final int grandTotal;  final dynamic couponCode;  factory Summary.fromJson(Map<String, dynamic> json){    return Summary(      subtotal: json["subtotal"] ?? 0,      couponDiscount: json["coupon_discount"] ?? 0,      deliveryCharge: json["delivery_charge"] ?? 0,      grandTotal: json["grand_total"] ?? 0,      couponCode: json["coupon_code"],    );  }  Map<String, dynamic> toJson() => {    "subtotal": subtotal,    "coupon_discount": couponDiscount,    "delivery_charge": deliveryCharge,    "grand_total": grandTotal,    "coupon_code": couponCode,  };}